//! Static MetaObject data model (ADR 0002): read-only descriptors generated by
//! `rt-macros` at derive time; no runtime assembly.

use core::any::{Any, TypeId};

/// A type referenced by a descriptor: display name plus exact identity.
#[derive(Debug, PartialEq, Eq)]
pub struct TypeRef {
    /// Display-only rendering of the type; identity lives in `id`.
    pub name: &'static str,
    pub id: TypeId,
}

/// Climbs `up` parent-value fields from an erased receiver, starting at the
/// type whose MetaObject carries the route. Generated by `#[derive(Object)]`
/// for types with `#[object(parent = ..)]`; plain fn pointer, static data.
pub type ParentRoute = fn(&mut dyn Any, u8) -> &mut dyn Any;

/// Receiver routing for a by-name slot invocation: when the resolved invoker
/// lives on an ancestor level, the erased receiver (an instance of the
/// derived type) must first be routed up to the ancestor's value field.
#[derive(Debug, Clone, Copy)]
pub struct SlotRoute {
    pub route: Option<ParentRoute>,
    /// Levels to climb; `0` for slots owned by the receiver's own type.
    pub up: u8,
}

impl SlotRoute {
    /// Own-level invocation: no routing.
    pub const DIRECT: Self = Self {
        route: None,
        up: 0,
    };

    /// Hands back the receiver the invoker's owner type expects.
    pub fn resolve(self, recv: &mut dyn Any) -> &mut dyn Any {
        match self.route {
            Some(route) if self.up > 0 => route(recv, self.up),
            _ => recv,
        }
    }
}

/// Erased constructor for a registered kind: hands back a fresh, fully
/// initialized value plus the property hook the Hub insert path needs.
/// Plain fn pointers — static data, like the descriptors (ADR 0002).
#[derive(Debug, Clone)]
pub struct ObjectFactory {
    pub construct: fn() -> Box<dyn Any>,
    pub props: fn(&mut dyn Any) -> Option<&mut dyn crate::property::PropertyInputs>,
}

/// Invokes a slot on an erased receiver with an erased payload; generated by
/// `#[slot]`. Returns the slot's value erased (`None` for unit returns).
/// The [`SlotRoute`] routes the receiver up the parent chain when the invoker
/// belongs to an ancestor level. Plain fn pointer — static data, only
/// reachable through the feature-gated by-name path.
pub type SlotInvoker = fn(&mut dyn Any, Box<dyn Any>, SlotRoute) -> Option<Box<dyn Any>>;

/// A named occurrence objects may emit; delivered, never coalesced.
#[derive(Debug, PartialEq, Eq)]
pub struct SignalDescriptor {
    pub name: &'static str,
    pub args: &'static [TypeRef],
    /// The payload a delivery carries: unit, the bare single argument, or
    /// the argument tuple — exactly what `Hub::emit` receives as `Args`.
    pub payload: TypeRef,
}

/// A named operation offered in response to signals.
#[derive(Debug, PartialEq, Eq)]
pub struct SlotDescriptor {
    pub name: &'static str,
    pub args: &'static [TypeRef],
    /// The payload this slot's invoker accepts, mirroring the signal side.
    pub payload: TypeRef,
    /// Unit (`()`) when the slot returns nothing.
    pub ret: TypeRef,
}

/// Named state where only the latest value matters.
#[derive(Debug, PartialEq, Eq)]
pub struct PropertyDescriptor {
    pub name: &'static str,
    pub ty: TypeRef,
}

/// The static description of a kind of object: members and parent kind.
#[derive(Debug)]
pub struct MetaObject {
    pub type_name: &'static str,
    /// Parent kind link as a thunk over its own static MetaObject.
    pub parent: Option<fn() -> &'static MetaObject>,
    pub signals: &'static [SignalDescriptor],
    pub slots: &'static [SlotDescriptor],
    pub properties: &'static [PropertyDescriptor],
    /// Slot invokers keyed by name; the by-name dispatch path (feature
    /// `dynamic-invoke`) reads this table. Static data like the descriptors.
    /// Own members only — inherited slots resolve through the chain.
    pub slot_invokers: &'static [(&'static str, SlotInvoker)],
    /// Erased constructor for this kind; `Some` when the derive saw
    /// `#[object(default = expr)]` or `#[object(default)]` (falling back to
    /// `Default`). Absent kinds are not by-name constructible.
    pub factory: Option<ObjectFactory>,
    /// Climbs from an instance of this type to an ancestor's value field;
    /// `Some` exactly when `parent` is `Some`. The by-name slot path composes
    /// it with the resolved level into a [`SlotRoute`].
    pub parent_route: Option<ParentRoute>,
}

impl MetaObject {
    /// The parent kind's MetaObject, at the same address `Parent::meta()` returns.
    pub fn parent_meta(&self) -> Option<&'static MetaObject> {
        self.parent.map(|parent| parent())
    }

    /// Merged signal lookup across this type's parent chain (this level
    /// first): the index lives in the merged space — own signals keep their
    /// own-space indices, each ancestor level's signals append after the
    /// younger levels' signal counts. Because registration rejects
    /// duplicate names across the chain, the first match is the only match.
    pub fn find_signal_merged(&'static self, name: &str) -> Option<(u32, &'static SignalDescriptor)> {
        let mut offset = 0u32;
        let mut level = Some(self);
        while let Some(meta) = level {
            for (index, signal) in meta.signals.iter().enumerate() {
                if signal.name == name {
                    return Some((offset + index as u32, signal));
                }
            }
            offset += meta.signals.len() as u32;
            level = meta.parent_meta();
        }
        None
    }

    /// Merged slot descriptor lookup: returns the owner level (`0` = own) so
    /// the caller can route the receiver before invoking.
    pub fn find_slot_merged(&'static self, name: &str) -> Option<(&'static SlotDescriptor, u8)> {
        let mut up = 0u8;
        let mut level = Some(self);
        while let Some(meta) = level {
            if let Some(slot) = meta.slots.iter().find(|slot| slot.name == name) {
                return Some((slot, up));
            }
            up += 1;
            level = meta.parent_meta();
        }
        None
    }

    /// Merged invoker lookup: walks the chain and returns the owning level's
    /// own invoker. The caller pairs it with the level from
    /// [`MetaObject::find_slot_merged`] to build the [`SlotRoute`].
    pub fn slot_invoker_merged(&'static self, name: &str) -> Option<SlotInvoker> {
        let mut level = Some(self);
        while let Some(meta) = level {
            if let Some((_, invoker)) = meta.slot_invokers.iter().find(|(n, _)| *n == name) {
                return Some(*invoker);
            }
            level = meta.parent_meta();
        }
        None
    }

    /// Merged property lookup across the chain: each level's property space
    /// (its own indices already sit after its signals) appends after the
    /// whole signal+property space of the younger levels, so the merged
    /// property table is the chain flattened in declaration order.
    pub fn find_property_merged(
        &'static self,
        name: &str,
    ) -> Option<(u32, &'static PropertyDescriptor)> {
        let mut offset = 0u32;
        let mut level = Some(self);
        while let Some(meta) = level {
            for (index, property) in meta.properties.iter().enumerate() {
                if property.name == name {
                    return Some((offset + meta.signals.len() as u32 + index as u32, property));
                }
            }
            offset += (meta.signals.len() + meta.properties.len()) as u32;
            level = meta.parent_meta();
        }
        None
    }

    /// Whether this chain contains `ancestor`: walks the parent links
    /// comparing static addresses — the parent thunk is guaranteed to return
    /// the same static MetaObject the parent kind's `meta()` does, so
    /// address equality is kind equality. Reflexive: a kind is its own
    /// ancestor.
    pub fn inherits(&self, ancestor: &MetaObject) -> bool {
        let mut level = Some(self);
        while let Some(current) = level {
            if core::ptr::eq(current, ancestor) {
                return true;
            }
            level = current.parent_meta();
        }
        false
    }

    /// Signals of the whole chain, own level first, declaration order within
    /// a level; each entry carries its owning level (`0` = own).
    pub fn signal_chain(&'static self) -> Vec<(&'static SignalDescriptor, u8)> {
        let mut out = Vec::new();
        let mut up = 0u8;
        let mut level = Some(self);
        while let Some(meta) = level {
            out.extend(meta.signals.iter().map(|s| (s, up)));
            up += 1;
            level = meta.parent_meta();
        }
        out
    }

    /// Slots of the whole chain, own level first, declaration order within
    /// a level; each entry carries its owning level (`0` = own).
    pub fn slot_chain(&'static self) -> Vec<(&'static SlotDescriptor, u8)> {
        let mut out = Vec::new();
        let mut up = 0u8;
        let mut level = Some(self);
        while let Some(meta) = level {
            out.extend(meta.slots.iter().map(|s| (s, up)));
            up += 1;
            level = meta.parent_meta();
        }
        out
    }

    /// Properties of the whole chain, own level first, declaration order
    /// within a level; each entry carries its owning level (`0` = own).
    pub fn property_chain(&'static self) -> Vec<(&'static PropertyDescriptor, u8)> {
        let mut out = Vec::new();
        let mut up = 0u8;
        let mut level = Some(self);
        while let Some(meta) = level {
            out.extend(meta.properties.iter().map(|p| (p, up)));
            up += 1;
            level = meta.parent_meta();
        }
        out
    }
}

/// A kind of object with a static MetaObject; implemented by `#[derive(Object)]`.
///
/// # Example
/// ```
/// use rt_core::{Object, object_impl};
///
/// #[derive(Object)]
/// struct Widget;
///
/// #[object_impl]
/// impl Widget {
///     #[signal]
///     fn pressed(&self, button: u8);
///
///     #[slot]
///     fn release(&mut self) {}
/// }
///
/// let meta = Widget::meta();
/// assert_eq!(meta.signals[0].name, "pressed");
/// assert_eq!(meta.slots[0].name, "release");
/// ```
pub trait Object: crate::property::PropertyInputs {
    /// The static description of this kind of object; no runtime allocation.
    fn meta() -> &'static MetaObject;
}

/// Signal/slot descriptors harvested from the type's `#[object_impl]` block.
/// Every `#[derive(Object)]` type needs exactly one `#[object_impl]` impl.
pub trait ObjectInputs {
    const SIGNALS: &'static [SignalDescriptor];
    const SLOTS: &'static [SlotDescriptor];
    const SLOT_INVOKERS: &'static [(&'static str, SlotInvoker)];
}
